// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Schedule an operation with zero delay
        address target = address(0x1);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(uint256(1));
        c.schedule(target, value, data, predecessor, salt, 0);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Try to cancel the operation
        bool ok = false;
        try c.cancel(id) {
            ok = true;
        } catch {
            ok = false;
        }

        // In reference, isOperationPending returns true -> cancel succeeds -> ok = true
        // In mutant, supportsInterface returns true (always), but that doesn't affect cancel directly.
        // The buggy version does not modify the behavior of cancel because the change is only in supportsInterface.
        // Actually the mutant changes supportsInterface but cancel does not call it. So both should have the same behavior.
        // But the problem statement says they differ via supportsInterface args that complete and return different values.
        // The given difference is about supportsInterface, not cancel. So the test should focus on supportsInterface.
        // Let's test supportsInterface exactly.

        // This scenario: supportsInterface(0x01ffc9a7) is the ERC165 interface ID.
        // Reference returns true; mutant also returns true (since mutant always returns true).
        // For a different interface ID, say 0xffffffff, reference returns false, mutant returns true.
        // So:
        bool refResult = c.supportsInterface(0xffffffff);
        // In reference this returns false, in mutant returns true.
        assertTrue(refResult == false, "supportsInterface should return false for invalid id");
    }
}

