pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Deploy with proposer and executor set to address(this).
        // Schedule an operation with delay 0 so it can be executed immediately.
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(0);
        uint256 delay = 0;
        c.schedule(target, value, data, predecessor, salt, delay);

        // Execute the operation to mark it done.
        c.execute(target, value, data, predecessor, salt);

        // Now cancel the same operation (which is done, not pending).
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // In the reference, cancel reverts because isOperationPending returns false.
        // In the buggy version, the caller (address(this)) has PROPOSER_ROLE,
        // but due to buggy supportsInterface, the onlyRole modifier does not revert
        // and cancel proceeds to revert because isOperationPending returns false.
        // Both revert, so we need a different approach: call cancel from an address
        // without PROPOSER_ROLE. In reference, onlyRole reverts; in bug, onlyRole
        // does not revert due to bad supportsInterface, so cancel proceeds and
        // reverts with "operation cannot be cancelled". The revert reason differs:
        // reference reverts with "AccessControl:...missing role...", bug reverts with
        // "TimelockController: operation cannot be cancelled".

        // Use a fresh address without any role.
        address attacker = address(0xabcd);
        vm.prank(attacker);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.cancel.selector, id));

        // Reference: ok is false (reverted due to missing role).
        // Buggy: ok is true (call succeeded, but revert with different reason? No, cancel reverts with "operation cannot be cancelled").
        // Actually both revert, so ok is false for both. Need a different observable.
        // Let's directly test supportsInterface.

        // The difference: supportsInterface(IAccessControl.interfaceId) returns true in reference, false in bug.
        bytes4 interfaceId = type(IAccessControl).interfaceId;
        bool result = c.supportsInterface(interfaceId);
        assertTrue(result, "supportsInterface should return true for IAccessControl");
    }
}

interface IAccessControl {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

