    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Schedule an operation (needs PROPOSER_ROLE, which address(this) has)
        bytes32 id = c.hashOperation(address(0), 0, "", bytes32(0), bytes32(0));
        c.schedule(address(0), 0, "", bytes32(0), bytes32(0), 0);
        // Renounce EXECUTOR_ROLE (address(this) also has that role from constructor)
        c.renounceRole(c.EXECUTOR_ROLE(), address(this));
        // Warp past delay to make operation ready
        vm.warp(block.timestamp + 1);
        // Attempt to execute — this calls _beforeCall and _call, then _afterCall
        // _afterCall checks hasRole(EXECUTOR_ROLE, msg.sender) — in reference it returns true (still has role? Actually renounceRole revoked it, so false → revert? Wait: Renouncing EXECUTOR_ROLE makes hasRole return false. But we haven't executed yet. Let's instead test cancel: cancel only needs PROPOSER_ROLE, not EXECUTOR_ROLE.)
        // Simpler: cancel a pending operation after renouncing EXECUTOR_ROLE, which should work (cancel only checks PROPOSER_ROLE).
        // Actually the difference: In the bug, hasRole for EXECUTOR_ROLE is inverted, but cancel does not check EXECUTOR_ROLE. So we need a scenario where the buggy hasRole affects the outcome of cancel? Not directly.
        // The property must use cancel? The mutant changes hasRole; cancel uses onlyRole(PROPOSER_ROLE) which calls _checkRole which uses hasRole for PROPOSER_ROLE. So invert that makes cancel revert incorrectly.
        // Let's set up: address(this) has PROPOSER_ROLE. In reference, hasRole(PROPOSER_ROLE, address(this)) = true → cancel succeeds. In bug, hasRole returns false → cancel reverts.
        // So:
        // 1. Schedule an operation (needs PROPOSER_ROLE, works in both).
        // 2. Call cancel — in reference succeeds (hasRole returns true), in bug reverts (hasRole returns false).
        // 3. Assert that cancel succeeded in reference and failed in bug.
        c.schedule(address(0), 0, "", bytes32(0), bytes32(0), 0);
        bool ok;
        try c.cancel(id) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

