import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Grant EXECUTOR_ROLE to address(0) to make it an open role
        bytes32 EXECUTOR_ROLE = keccak256("EXECUTOR_ROLE");
        c.grantRole(EXECUTOR_ROLE, address(0));

        // Schedule an operation
        bytes32 salt = bytes32(uint256(1));
        bytes32 id = c.hashOperation(address(0), 0, "", bytes32(0), salt);
        c.schedule(address(0), 0, "", bytes32(0), salt, 1);

        // Warp past the delay
        vm.warp(block.timestamp + 2);

        // Execute as address(0) - the buggy _afterCall checks hasRole(EXECUTOR_ROLE, msg.sender)
        // In P: hasRole(EXECUTOR_ROLE, address(0)) returns true
        // In M: hasRole(EXECUTOR_ROLE, address(0)) returns false, causing revert
        bool ok;
        vm.prank(address(0));
        try c.execute(address(0), 0, "", bytes32(0), salt) {
            ok = true;
        } catch {
            ok = false;
        }

        // P succeeds (ok = true), M reverts (ok = false)
        assertTrue(ok);
    }
}

