import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    function testRegression_property() public {
        // Grant EXECUTOR_ROLE to address(0) to make it open (anyone can execute)
        c.grantRole(c.EXECUTOR_ROLE(), address(0));

        // Schedule an operation as proposer (msg.sender is proposer from constructor)
        address target = address(0x1234);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(uint256(1));
        uint256 delay = 1;
        c.schedule(target, value, data, predecessor, salt, delay);

        // Warp past the delay
        vm.warp(block.timestamp + delay + 1);

        // Execute as any non-executor address (since role is open, anyone can execute)
        address executor = address(0xdead);
        bytes32 operationId = c.hashOperation(target, value, data, predecessor, salt);

        bool success;
        try c.execute{value: 0}(target, value, data, predecessor, salt) {
            success = true;
        } catch {
            success = false;
        }

        // In the reference (P), execute succeeds and timestamps becomes 1 (done).
        // In the buggy (M), hasRole(EXECUTOR_ROLE, msg.sender) returns !false = true,
        // but then _checkRole in execute? Wait, execute uses onlyRoleOrOpenRole which checks
        // if !hasRole(role, address(0)) then _checkRole, but here hasRole(address(0)) is true (because granted),
        // so the modifier passes. However _afterCall checks hasRole(EXECUTOR_ROLE, _msgSender()) directly.
        // In reference: hasRole returns true if role is open (address(0) has role), but _afterCall checks sender,
        // not address(0). So reference requires actual executor role for sender.
        // Actually, in reference, _afterCall uses hasRole(EXECUTOR_ROLE, _msgSender()) — since executor is not
        // the msg.sender and address(0) is not msg.sender, this returns false and reference would also revert.
        // Let me reconsider.
        // 
        // The difference: hasRole(EXECUTOR_ROLE, address(0)) returns: reference true (since granted), buggy false (inverted).
        // onlyRoleOrOpenRole: checks if !hasRole(role, address(0)) then _checkRole(sender).
        // Reference: hasRole(role, address(0)) == true, so !true == false, so no _checkRole — passes.
        // Buggy: hasRole(role, address(0)) == false, so !false == true, so _checkRole runs, which checks sender's role.
        // So buggy reverts in modifier before even reaching the function body.
        // Thus, execute reverts in M but succeeds in P.
        // So assertion: success is true in P (reference passes).

        assertTrue(success, "Execute should succeed when EXECUTOR_ROLE is open");
    }
}

