contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        bytes32 proposalId = keccak256("test");
        // Set up a pending operation: call schedule with this contract as proposer (since address(this) is granted PROPOSER_ROLE in constructor)
        c.schedule(address(0), 0, "", bytes32(0), keccak256("salt"), 1 days);
        // Renounce PROPOSER_ROLE
        c.renounceRole(c.PROPOSER_ROLE(), address(this));
        // Now cancel with this contract (no longer proposer) should revert in reference, but we need a scenario where reference succeeds and bug fails.
        // Actually, renouncing PROPOSER_ROLE makes cancel revert for both (needs proposer). So wrong approach.
        // Instead, keep PROPOSER_ROLE and use the difference in EXECUTOR_ROLE check in _afterCall via execute.
        // Simpler: schedule, then execute with EXECUTOR_ROLE open (grant to address(0)). Reference completes, bug reverts in _afterCall.
        bytes32 id = c.hashOperation(address(0), 0, "", bytes32(0), keccak256("salt"));
        // Grant EXECUTOR_ROLE to address(0) to make it open role
        c.grantRole(c.EXECUTOR_ROLE(), address(0));
        // Now execute (role check passes for both, but _afterCall checks hasRole(EXECUTOR_ROLE, msg.sender) for timelock)
        // Arrange: warp to after delay
        vm.warp(block.timestamp + 1 days + 1);
        // Execute; reference succeeds (hasRole returns true for address(0)), bug reverts because hasRole returns false for address(0)
        // But wait: msg.sender address(this) does NOT have EXECUTOR_ROLE, only address(0) does. The modifier onlyRoleOrOpenRole checks: if !hasRole(role, address(0)) then _checkRole. Since hasRole(EXECUTOR_ROLE, address(0)) is true in reference, it skips _checkRole, so it passes. In bug, hasRole returns false, so it does _checkRole and reverts because msg.sender lacks EXECUTOR_ROLE.
        // Thus execute reverts in M, succeeds in P.
        // Let's capture success via try/catch.
        bool success = false;
        try c.execute(address(0), 0, "", bytes32(0), keccak256("salt")) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success, "Reference should succeed, bug should revert");
    }
}

