        setUp();

        // Grant roles
        c.grantRole(c.PROPOSER_ROLE(), proposer);
        c.grantRole(c.EXECUTOR_ROLE(), executor);

        // Proposer schedules an operation
        vm.prank(proposer);
        c.schedule(address(0), 0, "", bytes32(0), bytes32(uint256(1)), 1 days);
        bytes32 id2 = c.hashOperation(address(0), 0, "", bytes32(0), bytes32(uint256(1)));

        // Attacker calls renounceRole for proposer (exploit bug: renounceRole should only allow self)
        bool renounceSuccess;
        vm.prank(attacker);
        try c.renounceRole(c.PROPOSER_ROLE(), proposer) {
            renounceSuccess = true;
        } catch {
            renounceSuccess = false;
        }

        // In reference: renounceSuccess is false (reverts with "AccessControl: can only renounce roles for self")
        // In bug: renounceSuccess is true (buggy renounceRole removes PROPOSER_ROLE from proposer)

        // Now attacker attempts to cancel the operation (which requires PROPOSER_ROLE)
        bool cancelSuccess;
        vm.prank(attacker);
        // The cancel will revert if attacker does not have PROPOSER_ROLE
        if (renounceSuccess) {
            // In bug, attacker managed to remove proposer's role, but does attacker now have PROPOSER_ROLE? No.
            // Actually cancel requires PROPOSER_ROLE, which attacker doesn't have. So cancel still fails.
            // The correct attack: after renouncing proposer role from proposer, the attacker still cannot cancel.
            // Need another approach: use buggy renounceRole to give attacker PROPOSER_ROLE?
            // Wait, renounceRole only revokes, not grants.
            // The bug: renounceRole can be called by anyone for any account, revoking that role from that account.
            // So attacker can revoke PROPOSER_ROLE from proposer, but that doesn't give attacker the role.
            // However, if there is a way to make cancel call succeed without PROPOSER_ROLE? No.
            // The difference must be observed differently: the buggy renounceRole allows anyone to revoke any role from any account.
            // So attacker can revoke the EXECUTOR_ROLE from executor, making some function fail.
            // But cancel has onlyRole(PROPOSER_ROLE), so revoking EXECUTOR_ROLE doesn't help cancel.
            // The only direct observable divergence is whether renounceRole itself reverts.
        }

        // Assert that the renounceRole call behavior differs: reference reverts, bug does not.
        assertTrue(renounceSuccess == false, "In reference, renounceRole should revert");
    }
}

